def split_gpxs(xml: AnyStr) ->Iterable[str]:
    dom = mod_minidom.parseString(xml)
    gpx_node = _find_gpx_node(dom)
    if not gpx_node:
        return []

    gpx_nodes = []
    for child_node in gpx_node.childNodes:
        if child_node.nodeName == 'trk':
            gpx_nodes.append(child_node)

    result = []
    for gpx_node in gpx_nodes:
        new_dom = mod_minidom.parseString('<gpx></gpx>')
        new_gpx = _find_gpx_node(new_dom)
        new_gpx.appendChild(gpx_node)
        result.append(new_dom.toxml())

    return result

def _find_gpx_node(dom: Any) ->Any:
    for node in dom.getElementsByTagName('gpx'):
